  1287  M3Result  Compile_BranchTable  (IM3Compilation o, m3opcode_t i_opcode)
  1288  {
  1289      M3Result result;
  1290
  1291  _try {
  1292      u32 targetCount;
  1293  _   (ReadLEB_u32 (& targetCount, & o->wasm, o->wasmEnd));
  1294
  1295  _   (PreserveRegisterIfOccupied (o, c_m3Type_i64));         // move branch operand to a slot
  1296      u16 slot = GetStackTopSlotIndex (o);
  1297  _   (Pop (o));
  1298
  1299      // OPTZ: according to spec: "forward branches that target a control instruction with a non-empty
  1300      // result type consume matching operands first and push them back on the operand stack after unwinding"
  1301      // So, this move-to-reg is only necessary if the target scopes have a type.
  1302      if (GetNumBlockValues (o) > 0)
  1303  _      (MoveStackTopToRegister (o));
  1304
  1305      u32 numCodeLines = targetCount + 4; // 3 => IM3Operation + slot + target_count + default_target
  1306  _   (EnsureCodePageNumLines (o, numCodeLines));
  1307
  1308  _   (EmitOp (o, op_BranchTable));
  1309      EmitSlotOffset (o, slot);
  1310      EmitConstant32 (o, targetCount);
  1311
  1312      IM3CodePage continueOpPage = NULL;
  1313
  1314      ++targetCount; // include default
  1315      for (u32 i = 0; i < targetCount; ++i)
  1316      {
  1317          u32 target;
  1318  _       (ReadLEB_u32 (& target, & o->wasm, o->wasmEnd));
  1319
  1320          IM3CompilationScope scope;
  1321  _       (GetBlockScope (o, & scope, target));
  1322
  1323          if (scope->opcode == c_waOp_loop)
  1324          {
  1325              // create a ContinueLoop operation on a fresh page
  1326  _           (AcquireCompilationCodePage (o, & continueOpPage));
  1327
  1328              pc_t startPC = GetPagePC (continueOpPage);
  1329              EmitPointer (o, startPC);
  1330
  1331              IM3CodePage savedPage = o->page;
  1332              o->page = continueOpPage;
  1333
  1334  _           (EmitOp (o, op_ContinueLoop));
  1335              EmitPointer (o, scope->pc);
  1336
  1337              ReleaseCompilationCodePage (o);     // FIX: continueOpPage can get lost if thrown
  1338              o->page = savedPage;
  1339          }
  1340          else
  1341          {
  1342              IM3BranchPatch patch = NULL;
  1343  _           (AcquirePatch (o, & patch));
  1344
  1345              patch->location = (pc_t *) ReservePointer (o);
  1346              patch->next = scope->patches;
  1347              scope->patches = patch;
  1348          }
  1349      }
  1350
  1351      o->block.isPolymorphic = true;
  1352
  1353      }
  1354
  1355      _catch: return result;
  1356  }
